  {
    "path": "tools.team_tasks_list",
    "description": "View the shared team task board. Use this to check task status, not to wait for teammates. Teammates will message you when done.",
    "signature": "tools.team_tasks_list(): Promise<string | null>"
  },
  {
    "path": "tools.team_tasks_add",
    "description": "Add tasks to the shared team task board so teammates can see what work is available and claim it.",
    "signature": "tools.team_tasks_add({
  /** Tasks to add */
  tasks: Array<{
      /** Task description */
      content: string,
      /** Task priority. @default "medium" */
      priority?: "high" | "medium" | "low",
      /** Task IDs this depends on */
      depends_on?: Array<string>,
      /** Agent type affinity for auto-dispatch (e.g. build). Omit for any member. */
      agent?: string,
      /** Task complexity for deterministic model routing. @integer @minimum 0 @maximum 100 */
      complexity?: number,
      /** Task risk for model routing only (not review policy). @integer @minimum 0 @maximum 100 */
      risk?: number,
      /** Explicit task kind supplied to the fixed classification protocol */
      task_type?: string,
      /** Task-specific classification data, treated as data rather than instructions */
      classification_input?: {},
    }>,
}): Promise<string | null>"
  },
  {
    "path": "tools.team_claim",
    "description": "Claim a pending task from the shared task list. Only unclaimed, unblocked tasks can be claimed.",
    "signature": "tools.team_claim({
  /** ID of the task to claim */
  task_id: string,
}): Promise<string | null>"
  },
  {
    "path": "tools.team_tasks_complete",
    "description": "Mark a task as completed on the shared board. This unblocks any tasks that depend on it.",
    "signature": "tools.team_tasks_complete({
  /** ID of the task to mark complete */
  task_id: string,
}): Promise<string | null>"
  },
  {
    "path": "tools.grepai.grepai_1mcp_grepai_list_projects",
    "description": "List all projects within a workspace. Use this to discover project names and file paths relative to their project roots, which informs how to use the --path parameter in grepai_search.",
    "signature": "tools.grepai.grepai_1mcp_grepai_list_projects({
  /** Output format: 'json' (default) or 'toon' (token-efficient) */
  format?: string,
  /** Name of the workspace to list projects for (optional when mcp-serve was started with --workspace) */
  workspace?: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.team_handoff",
    "description": "V2: switch your own team session to another agent for subsequent provider turns, retaining its history, identity, tasks and worktree. This does not grant lead privileges.",
    "signature": "tools.team_handoff({
  /** Native target agent name */
  agent: string,
}): Promise<string | null>"
  },
  {
    "path": "tools.team_status",
    "description": "View team members with their current status, agent type, and session IDs. Use this to check who is working, idle, or shut down. Includes a task summary.",
    "signature": "tools.team_status(): Promise<string | null>"
  },
  {
    "path": "tools.grepai.grepai_1mcp_grepai_search",
    "description": "Semantic code search. Search your codebase using natural language queries. Returns the most relevant code chunks with file paths, line numbers, and similarity scores.

Examples:
- workspace-only mode: workspace='acme', path='src/'
- workspace + projects mode: workspace='acme', projects='backend,shared', path='api/'",
    "signature": "tools.grepai.grepai_1mcp_grepai_search({
  /** Return minimal output without content (default: false) */
  compact?: boolean,
  /** Output format: 'json' (default) or 'toon' (token-efficient) */
  format?: string,
  /** Maximum number of results to return (default: 10) */
  limit?: number,
  /**
   * Path prefix to filter results. When projects is set, path is relative to each selected project root (not workspace root). Examples: workspace-only path='src/' and workspace+projects path='MM32/src' or 'api/'.
   */
  path?: string,
  /** Comma-separated list of project names to search within workspace (requires workspace) */
  projects?: string,
  /** Natural language search query (e.g., 'user authentication flow', 'error handling middleware') */
  query: string,
  /**
   * Absolute project root path. When provided, the server will load configuration/index from this path (overrides server startup project). Optional.
   */
  root?: string,
  /** Workspace name for cross-project search (optional) */
  workspace?: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.grepai.grepai_1mcp_grepai_list_workspaces",
    "description": "List all available workspace names. Use this to discover valid values for tools that accept the workspace parameter.",
    "signature": "tools.grepai.grepai_1mcp_grepai_list_workspaces({
  /** Output format: 'json' (default) or 'toon' (token-efficient) */
  format?: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.grepai.grepai_1mcp_grepai_rpg_search",
    "description": "Search RPG nodes using Jaccard-based semantic matching with scope and kind filtering.",
    "signature": "tools.grepai.grepai_1mcp_grepai_rpg_search({
  /** Output format: 'json' (default) or 'toon' (token-efficient) */
  format?: string,
  /** Comma-separated node kinds to filter: area, category, subcategory, file, symbol, chunk (default: symbol) */
  kinds?: string,
  /** Maximum number of results to return (default: 10) */
  limit?: number,
  /** Natural language or feature query to search for */
  query: string,
  /** Area/category path to narrow search (e.g., 'cli', 'rpg/query') */
  scope?: string,
}): Promise<unknown>"
  }
]
